create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_LOGISTIC_VARIANT_2 (
	LOGISTIC_VARIANT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a logistic variant of a product.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	LOGISTIC_VARIANT_NR VARCHAR(20) COMMENT 'The number by which the logistic variant is known to business.',
	LOGISTIC_VARIANT_NAME VARCHAR(500) NOT NULL COMMENT 'The name of the logistic variant.',
	LOGISTIC_VARIANT_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for logistic variants.',
	LOGISTIC_VARIANT_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for logistic variants. (Description in group language, i.e. in German)',
	PROD_VARIANT_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'A code that defines the lifecycle status_2 of the logistic variant,',
	PROD_VARIANT_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the status_2 code of a product variant in group language, i.e. in German.',
	CASE_SIZE_CNT NUMBER(38,0) NOT NULL COMMENT 'The number of individual items that are contained in the logistic variant. (Note that the individual item_2 represents the smallest sellable unit. E.g. if a packed try of meat contains two slices, the entire tray is considered one sellable unit.)',
	WEIGHT_BASED_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product variant is delivered by weight instead of count.',
	LENGTH_MEAS NUMBER(38,5) COMMENT 'The length of the logistic variant, expressed in the indicated unit_2 of measure.',
	WIDTH_MEAS NUMBER(38,5) COMMENT 'The width of the logistic variant, expressed in the indicated unit_2 of measure.',
	HEIGHT_MEAS NUMBER(38,5) COMMENT 'The height of the logistic variant, expressed in the indicated unit_2 of measure.',
	SIZE_UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit_2 of measure for the length, width and height.',
	NET_WEIGHT_MEAS NUMBER(38,5) COMMENT 'The net weight (i.e. excluding packing material) of the logistic variant, expressed in the indicated unit_2 of measure.',
	GROSS_WEIGHT_MEAS NUMBER(38,5) COMMENT 'The gross weight (i.e. including packing material) of the logistic variant, expressed in the indicated unit_2 of measure.',
	WEIGHT_UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit_2 of measure.',
	UNITS_PER_PALLET_CNT NUMBER(38,0) COMMENT 'The number of logistic variants which can be packed on a pallet. (The type of pallet is indicated by the Pallet Type Code.)',
	UNITS_PER_PALLET_LAYER_CNT NUMBER(38,0) COMMENT 'The number of logistic variants which can be packed on one layer of a pallet. (The type of pallet is indicated by the Pallet Type Code.)',
	PALLET_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the kind of pallet. (Euro-pallet vs. Duesseldorfer pallet)',
	PALLET_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the kind of pallet. (Description in group language, i.e. in German)',
	PROD_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product, which is the base for this logistic variant.',
	PROD_NR VARCHAR(20) COMMENT 'The number which (globally) identifies the product which is the base for this logistic variant, within the organization. (Note that the product number is unique for a certain point in time, but may be re_2-used later on.)',
	PROD_NAME VARCHAR(250) NOT NULL COMMENT 'The name of the global product, which is the base for this logistic variant.',
	ITEM_FAM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the item_2 family, which contains this logistic variant.',
	ITEM_FAM_NR VARCHAR(100) COMMENT 'The number by which the related item_2 family is known to business.',
	ITEM_FAM_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related item_2 family in group language, i.e. in German.',
	SUB_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the sub item_2 group, which contains this logistic variant.',
	SUB_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related sub item_2 group is known to business.',
	SUB_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related sub item_2 group in group language, i.e. in German.',
	INT_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the international item_2 group, which contains this logistic variant.',
	INT_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related international item_2 group is known to business.',
	INT_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related international item_2 group in group language, i.e. in German.',
	PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the pillar, which contains this logistic variant.',
	PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related pillar is known to business.',
	PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related pillar in group language, i.e. in German.',
	MAIN_PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the main pillar, which contains this logistic variant.',
	MAIN_PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related main pillar is known to business.',
	MAIN_PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the related main pillar in group language, i.e. in German.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_LOGISTIC_VARIANT primary key (LOGISTIC_VARIANT_SID, DWH_VALID_FROM_TMSP)
)COMMENT='A logistic variant describes how a product is packed and transported. Typically it is not individual items that are shipped from the supplier_2 to the warehouse and from the warehouse to the store, but larger quantities of identical items are bundled into packets, e.g. cardboard boxes.The case size determines, how many items are contained in such a box.'
;